// Lee la configuración local del archivo .env sin mostrar secretos en pantalla.
var envFile = Path.Combine(Directory.GetCurrentDirectory(), ".env");
if (File.Exists(envFile)) foreach (var line in File.ReadAllLines(envFile)) {
    var p=line.Trim(); if (p.Length==0 || p.StartsWith('#') || !p.Contains('=')) continue;
    var i=p.IndexOf('='); Environment.SetEnvironmentVariable(p[..i].Trim(),p[(i+1)..].Trim());
}
var builder = WebApplication.CreateBuilder(args);
var appUrls=Environment.GetEnvironmentVariable("ASPNETCORE_URLS");
var appPort=Environment.GetEnvironmentVariable("PORT");
if(!string.IsNullOrWhiteSpace(appUrls))builder.WebHost.UseUrls(appUrls);
else if(int.TryParse(appPort,out var listenPort))builder.WebHost.UseUrls($"http://0.0.0.0:{listenPort}");
else builder.WebHost.UseUrls("http://127.0.0.1:5000");
var app = builder.Build();


var dbServer=Environment.GetEnvironmentVariable("DB_SERVER") ?? "localhost";
var dbInstance=Environment.GetEnvironmentVariable("DB_INSTANCE");
var serverName=string.IsNullOrWhiteSpace(dbInstance)?dbServer:$"{dbServer}\\{dbInstance}";
var connString=new SqlConnectionStringBuilder { DataSource=serverName, InitialCatalog=Environment.GetEnvironmentVariable("DB_DATABASE") ?? "MexicoRuns2", UserID=Environment.GetEnvironmentVariable("DB_USER") ?? "sa", Password=Environment.GetEnvironmentVariable("DB_PASSWORD") ?? "", TrustServerCertificate=bool.TryParse(Environment.GetEnvironmentVariable("DB_TRUST_SERVER_CERTIFICATE"),out var trustCert)?trustCert:true, Encrypt=bool.TryParse(Environment.GetEnvironmentVariable("DB_ENCRYPT"),out var encryptDb)?encryptDb:true, ConnectTimeout=8 }.ConnectionString;
if (int.TryParse(Environment.GetEnvironmentVariable("DB_PORT"),out var dbPort)) { var b=new SqlConnectionStringBuilder(connString){DataSource=$"{dbServer},{dbPort}"}; connString=b.ConnectionString; }

var sessions=new ConcurrentDictionary<string,UserSession>();
var roles=new[]{"CategoriasVehiculo","EstadosPago","EstadosReservacion","EstadosVehiculo","MetodosPago","Roles","Sucursales","CuentasCliente","Vehiculos","Mantenimientos","Reservaciones","Pagos","Opiniones"};
var jsonOptions=new JsonSerializerOptions{PropertyNameCaseInsensitive=true};
string? Cookie(HttpContext c)=>c.Request.Cookies["mr_session"];
UserSession? Session(HttpContext c)=>Cookie(c) is string t && sessions.TryGetValue(t,out var u)?u:null;
IResult? Deny(HttpContext c,string? role=null){var u=Session(c);if(u is null)return Results.Json(new{success=false,message="Inicia sesión para continuar."},statusCode:401);if(u.MustChange)return Results.Json(new{success=false,message="Actualiza tu contraseña para continuar.",mustChange=true},statusCode:403);if(role is not null && u.Role!=role && !(role=="Empleado"&&u.Role=="Administrador"))return Results.Json(new{success=false,message="No tienes permiso para esta función."},statusCode:403);return null;}
async Task<List<Dictionary<string,object?>>> Query(string sql, params SqlParameter[] ps){await using var c=new SqlConnection(connString);await c.OpenAsync();await using var cmd=new SqlCommand(sql,c);cmd.Parameters.AddRange(ps);await using var r=await cmd.ExecuteReaderAsync();var list=new List<Dictionary<string,object?>>();while(await r.ReadAsync()){var row=new Dictionary<string,object?>(StringComparer.OrdinalIgnoreCase);for(int i=0;i<r.FieldCount;i++)row[r.GetName(i)]=await r.IsDBNullAsync(i)?null:r.GetValue(i);list.Add(row);}return list;}
string SqlDiagnostic(Exception ex,string area){if(ex is not SqlException se)return area+": no se pudo cargar. Revisa la terminal del servidor.";return se.Number switch{208=>area+": falta una tabla en MexicoRuns2. Detén y vuelve a iniciar con npm start para ejecutar la migración SQL.",207=>area+": la tabla existe pero falta una columna esperada. Revisa que se haya aplicado database/MejorasMexicoRuns.sql.",18456=>"SQL Server rechazó las credenciales de conexión.",4060=>"SQL Server no pudo abrir la base configurada; revisa DB_DATABASE en .env.",53=>"No se encuentra la instancia de SQL Server; revisa DB_SERVER y DB_INSTANCE en .env.",547=>area+": hay una relación entre registros que impide la operación.",_=>area+": error SQL "+se.Number+". Revisa la terminal de Mexico Runs para el detalle."};}
async Task<(List<Dictionary<string,object?>> Rows,string? Issue)> SafeQuery(string area,string sql){try{return(await Query(sql),null);}catch(Exception ex){return(new List<Dictionary<string,object?>>(),SqlDiagnostic(ex,area));}}async Task<int> Exec(string sql, params SqlParameter[] ps){await using var c=new SqlConnection(connString);await c.OpenAsync();await using var cmd=new SqlCommand(sql,c);cmd.Parameters.AddRange(ps);return await cmd.ExecuteNonQueryAsync();}
async Task<(List<Dictionary<string,object?>> Rows,Dictionary<string,object?> Out)> Proc(string name, IEnumerable<SqlParameter> ps){await using var c=new SqlConnection(connString);await c.OpenAsync();await using var cmd=new SqlCommand(name,c){CommandType=CommandType.StoredProcedure};cmd.Parameters.AddRange(ps.ToArray());var rows=new List<Dictionary<string,object?>>();await using(var r=await cmd.ExecuteReaderAsync()){do{while(await r.ReadAsync()){var row=new Dictionary<string,object?>(StringComparer.OrdinalIgnoreCase);for(int i=0;i<r.FieldCount;i++)row[r.GetName(i)]=await r.IsDBNullAsync(i)?null:r.GetValue(i);rows.Add(row);}}while(await r.NextResultAsync());}var output=cmd.Parameters.Cast<SqlParameter>().Where(p=>p.Direction is ParameterDirection.Output or ParameterDirection.InputOutput).ToDictionary(p=>p.ParameterName.TrimStart('@'),p=>p.Value is DBNull?null:p.Value,StringComparer.OrdinalIgnoreCase);return(rows,output);}
SqlParameter P(string n,SqlDbType t,object? v,int size=0){var p=size==0?new SqlParameter(n,t):new SqlParameter(n,t,size);p.Value=v??DBNull.Value;return p;}
SqlParameter Out(string n,SqlDbType t){return new SqlParameter(n,t){Direction=ParameterDirection.Output};}
async Task Audit(UserSession u,string action,string table,object? id,object? detail=null){try{await Exec("INSERT dbo.BitacoraAuditoria(id_usuario,rol,accion,tabla,id_registro,detalle) VALUES(@u,@r,@a,@t,@i,@d)",P("@u",SqlDbType.Int,u.Id),P("@r",SqlDbType.NVarChar,u.Role,50),P("@a",SqlDbType.NVarChar,action,50),P("@t",SqlDbType.NVarChar,table,128),P("@i",SqlDbType.NVarChar,id?.ToString(),100),P("@d",SqlDbType.NVarChar,JsonSerializer.Serialize(detail??new{}),-1));}catch{}}
async Task LogError(Exception ex){try{await Proc("dbo.sp_RegistrarError",new[]{P("@procedimiento",SqlDbType.NVarChar,".NET API",128),P("@numero_error",SqlDbType.Int,ex is SqlException se?se.Number:null),P("@severidad",SqlDbType.Int,null),P("@estado",SqlDbType.Int,null),P("@linea",SqlDbType.Int,null),P("@mensaje",SqlDbType.NVarChar,ex.Message,-1)});}catch{}}
IResult Error(Exception ex){Console.Error.WriteLine(ex.Message);_ = LogError(ex);var code=ex is SqlException sx && (sx.Number==2601||sx.Number==2627)?409:500;var msg=ex is SqlException d && (d.Number==2601||d.Number==2627)?"Ya existe un registro con ese correo, placa o serie.":SqlDiagnostic(ex,"La operación");return Results.Json(new{success=false,message=msg},statusCode:code);}
bool Strong(string? s)=>s is {Length:>=8}&&s.Any(char.IsLetter)&&s.Any(char.IsDigit)&&s.Any(c=>!char.IsLetterOrDigit(c));
string HashPassword(string p){var salt=RandomNumberGenerator.GetBytes(16);var h=Rfc2898DeriveBytes.Pbkdf2(p,salt,210000,HashAlgorithmName.SHA256,32);return $"pbkdf2${Convert.ToHexString(salt)}${Convert.ToHexString(h)}";}
bool VerifyPassword(string input,string? stored){if(stored is null)return false;try{var x=stored.Split('$');byte[] actual;if(x.Length==3&&x[0]=="pbkdf2")actual=Rfc2898DeriveBytes.Pbkdf2(input,Convert.FromHexString(x[1]),210000,HashAlgorithmName.SHA256,32);else if(x.Length==3&&x[0]=="scrypt")actual=Scrypt.Hash(input,Encoding.UTF8.GetBytes(x[1]),16384,8,1,Convert.FromHexString(x[2]).Length);else return input==stored;return CryptographicOperations.FixedTimeEquals(actual,Convert.FromHexString(x[2]));}catch{return false;}}
void LoginCookie(HttpContext c,UserSession u){var token=Convert.ToHexString(RandomNumberGenerator.GetBytes(32));sessions[token]=u;c.Response.Cookies.Append("mr_session",token,new CookieOptions{HttpOnly=true,SameSite=SameSiteMode.Lax,Path="/",MaxAge=TimeSpan.FromHours(8),Secure=c.Request.IsHttps});}
async Task<Dictionary<string,object?>?> Account(string email){var rows=await Query("SELECT c.*,r.nombre_rol AS __role FROM dbo.CuentasCliente c JOIN dbo.Roles r ON r.id=c.id_rol WHERE LOWER(c.correo)=LOWER(@e)",P("@e",SqlDbType.NVarChar,email.Trim().ToLowerInvariant(),100));return rows.FirstOrDefault();}
UserSession ToUser(Dictionary<string,object?> a)=>new(Convert.ToInt32(a["id"]),Convert.ToString(a["nombre"])??"",Convert.ToString(a["apellido_pat"])??"",Convert.ToString(a["correo"])??"",Convert.ToString(a["__role"])??"Cliente",Convert.ToBoolean(a.GetValueOrDefault("debe_cambiar_contrasena")??false));
async Task<List<Dictionary<string,object?>>> Reservations(string where="",params SqlParameter[] ps)=>await Query("SELECT r.id,r.id_cuenta_cliente,v.marca,v.modelo,v.placa,r.fecha_inicio,r.fecha_fin,r.costo_total,COALESCE((SELECT SUM(p.monto) FROM dbo.Pagos p JOIN dbo.EstadosPago ep ON ep.id=p.id_estado_pago WHERE p.id_reservacion=r.id AND ep.nombre=N'Pagado'),0) AS total_pagado,er.nombre AS estado FROM dbo.Reservaciones r JOIN dbo.Vehiculos v ON v.id=r.id_vehiculo JOIN dbo.EstadosReservacion er ON er.id=r.id_estado_reservacion "+where,ps);

// Aplica las mejoras idempotentes y los procedimientos almacenados de la base al iniciar.
try{await using var c=new SqlConnection(connString);await c.OpenAsync();var file=Path.Combine(app.Environment.ContentRootPath,"database","MejorasMexicoRuns.sql");var migration=System.Text.RegularExpressions.Regex.Replace(File.ReadAllText(file),@"^\s*USE\s+[\[\]\w.]+\s*;\s*$","",System.Text.RegularExpressions.RegexOptions.Multiline|System.Text.RegularExpressions.RegexOptions.IgnoreCase);foreach(var batch in System.Text.RegularExpressions.Regex.Split(migration,@"^\s*GO\s*$",System.Text.RegularExpressions.RegexOptions.Multiline|System.Text.RegularExpressions.RegexOptions.IgnoreCase).Where(x=>!string.IsNullOrWhiteSpace(x))){await using var cmd=new SqlCommand(batch,c);await cmd.ExecuteNonQueryAsync();}Console.WriteLine("Conectado a SQL Server; migraciones verificadas.");}catch(Exception ex){Console.Error.WriteLine("SQL Server/migración: "+ex.Message);}

app.Use(async (context,next)=>{if(context.Request.Path.Equals("/basededatos.html",StringComparison.OrdinalIgnoreCase)){var u=Session(context);if(u is null){context.Response.Redirect("/login.html");return;}if(u.Role!="Administrador"){context.Response.StatusCode=403;await context.Response.WriteAsync("Acceso exclusivo para cuentas Administrador.");return;}await context.Response.SendFileAsync(Path.Combine(app.Environment.WebRootPath,"basededatos.html"));return;}await next();});
app.UseDefaultFiles();app.UseStaticFiles();
app.MapGet("/api/health",async()=>{try{await using var c=new SqlConnection(connString);await c.OpenAsync();return Results.Ok(new{ok=true});}catch{return Results.Json(new{ok=false,message="SQL Server no está disponible."},statusCode:503);}});
app.MapGet("/api/sesion",(HttpContext c)=>{var u=Session(c);return Results.Ok(new{authenticated=u is not null,user=u is null?null:new{id=u.Id,nombre=u.Nombre,apellido_paterno=u.Apellido,correo=u.Email,rol=u.Role,mustChange=u.MustChange}});});
app.MapPost("/api/logout",(HttpContext c)=>{var token=Cookie(c);if(token is not null)sessions.TryRemove(token,out _);c.Response.Cookies.Delete("mr_session",new CookieOptions{Path="/"});return Results.Ok(new{success=true});});
app.MapPost("/api/login",async(HttpContext c,LoginDto d)=>{try{var a=await Account(d.correo);if(a is null||Convert.ToBoolean(a.GetValueOrDefault("bloqueada")??false)||!VerifyPassword(d.password,Convert.ToString(a.GetValueOrDefault("contrasena"))))return Results.Json(new{success=false,message="Correo, contraseña o tipo de cuenta incorrectos."},statusCode:401);var u=ToUser(a);if(!string.IsNullOrWhiteSpace(d.rol)&&d.rol!=u.Role)return Results.Json(new{success=false,message="Correo, contraseña o tipo de cuenta incorrectos."},statusCode:401);if(Convert.ToString(a.GetValueOrDefault("contrasena")) is string stored&&!stored.StartsWith("pbkdf2$")){await Exec("UPDATE dbo.CuentasCliente SET contrasena=@p WHERE id=@id",P("@p",SqlDbType.NVarChar,HashPassword(d.password),255),P("@id",SqlDbType.Int,u.Id));}LoginCookie(c,u);return Results.Ok(new{success=true,user=new{id=u.Id,nombre=u.Nombre,apellido_paterno=u.Apellido,correo=u.Email,rol=u.Role,mustChange=u.MustChange}});}catch(Exception ex){return Error(ex);}});
app.MapPost("/api/registro",async(HttpContext c,RegisterDto d)=>{if(!Strong(d.password)||!System.Text.RegularExpressions.Regex.IsMatch(d.correo,@"^\S+@\S+\.\S+$")||!System.Text.RegularExpressions.Regex.IsMatch(d.telefono,@"^\d{10}$"))return Results.BadRequest(new{success=false,message="Revisa el correo, el teléfono de 10 dígitos y la contraseña (8 caracteres, letra, número y símbolo)."});try{var output=Out("@id_cuenta",SqlDbType.Int);await Proc("dbo.sp_RegistrarCuentaCliente",new[]{P("@nombre",SqlDbType.NVarChar,d.nombre,50),P("@apellido_pat",SqlDbType.NVarChar,d.apellido_paterno,50),P("@apellido_mat",SqlDbType.NVarChar,d.apellido_materno,50),P("@telefono",SqlDbType.NVarChar,d.telefono,10),P("@correo",SqlDbType.NVarChar,d.correo.ToLowerInvariant(),100),P("@contrasena",SqlDbType.NVarChar,HashPassword(d.password),255),P("@numero_licencia",SqlDbType.NVarChar,d.licencia,30),P("@id_rol",SqlDbType.Int,null),output});var u=new UserSession(Convert.ToInt32(output.Value),d.nombre,d.apellido_paterno,d.correo,"Cliente",false);LoginCookie(c,u);return Results.Json(new{success=true,message="Cuenta creada. Ya iniciaste sesión.",user=new{id=u.Id,nombre=u.Nombre,rol=u.Role}},statusCode:201);}catch(Exception ex){return Error(ex);}});
app.MapPost("/api/cambiar-contrasena",async(HttpContext c,PasswordDto d)=>{var u=Session(c);if(u is null)return Deny(c)!;if(!Strong(d.password))return Results.BadRequest(new{success=false,message="Usa 8 caracteres, una letra, un número y un carácter especial."});try{await Exec("UPDATE dbo.CuentasCliente SET contrasena=@p,debe_cambiar_contrasena=0 WHERE id=@id",P("@p",SqlDbType.NVarChar,HashPassword(d.password),255),P("@id",SqlDbType.Int,u.Id));var token=Cookie(c);if(token is not null)sessions[token]=u with{MustChange=false};return Results.Ok(new{success=true,message="Contraseña actualizada."});}catch(Exception ex){return Error(ex);}});

app.MapGet("/api/catalogos",async()=>{try{return Results.Ok(new{sucursales=await Query("SELECT id,nombre,ciudad,estado FROM dbo.Sucursales ORDER BY nombre"),categorias=await Query("SELECT id,nombre,tarifa_diaria FROM dbo.CategoriasVehiculo ORDER BY tarifa_diaria"),metodosPago=await Query("SELECT id,nombre FROM dbo.MetodosPago ORDER BY id")});}catch(Exception ex){return Error(ex);}});
