app.MapGet("/api/vehiculos",async(HttpRequest req)=>{try{if(DateTime.TryParse(req.Query["inicio"],out var a)&&DateTime.TryParse(req.Query["fin"],out var b)){return Results.Ok(await Query("SELECT v.*,c.nombre categoria,c.tarifa_diaria,ev.nombre estado_vehiculo,s.nombre sucursal,s.ciudad FROM dbo.Vehiculos v LEFT JOIN dbo.CategoriasVehiculo c ON c.id=v.id_categoria JOIN dbo.EstadosVehiculo ev ON ev.id=v.id_estado_vehiculo LEFT JOIN dbo.Sucursales s ON s.id=v.id_sucursal WHERE ev.nombre IN(N'Disponible',N'Rentado') AND ISNULL(v.retirado,0)=0 AND NOT EXISTS(SELECT 1 FROM dbo.Reservaciones r JOIN dbo.EstadosReservacion er ON er.id=r.id_estado_reservacion WHERE r.id_vehiculo=v.id AND er.nombre IN(N'Pendiente',N'Confirmada',N'En curso') AND r.fecha_inicio<@b AND r.fecha_fin>@a) ORDER BY c.tarifa_diaria,v.marca,v.modelo",P("@a",SqlDbType.DateTime2,a),P("@b",SqlDbType.DateTime2,b)));}return Results.Ok(await Query("SELECT v.*,c.nombre categoria,c.tarifa_diaria,ev.nombre estado_vehiculo,s.nombre sucursal,s.ciudad FROM dbo.Vehiculos v LEFT JOIN dbo.CategoriasVehiculo c ON c.id=v.id_categoria JOIN dbo.EstadosVehiculo ev ON ev.id=v.id_estado_vehiculo LEFT JOIN dbo.Sucursales s ON s.id=v.id_sucursal WHERE ev.nombre=N'Disponible' AND ISNULL(v.retirado,0)=0 ORDER BY c.tarifa_diaria,v.marca,v.modelo"));}catch(Exception ex){return Error(ex);}});
app.MapGet("/api/admin/vehiculos",async(HttpContext c)=>{if(Deny(c,"Administrador") is IResult deny)return deny;try{return Results.Ok(await Query("SELECT v.*,cat.nombre categoria,cat.tarifa_diaria,ev.nombre estado_vehiculo,s.nombre sucursal,s.ciudad FROM dbo.Vehiculos v LEFT JOIN dbo.CategoriasVehiculo cat ON cat.id=v.id_categoria LEFT JOIN dbo.EstadosVehiculo ev ON ev.id=v.id_estado_vehiculo LEFT JOIN dbo.Sucursales s ON s.id=v.id_sucursal WHERE ISNULL(v.retirado,0)=0 ORDER BY v.id DESC"));}catch(Exception ex){return Error(ex);}});
app.MapPost("/api/admin/vehiculos",async(HttpContext c,JsonElement data)=>{if(Deny(c,"Administrador") is IResult deny)return deny;try{var d=data.Deserialize<Dictionary<string,JsonElement>>(jsonOptions)??new();var map=new Dictionary<string,string>{{"nombre","modelo"},{"marca","marca"},{"categoria","id_categoria"},{"precio","tarifa_diaria"},{"descripcion","descripcion"},{"imagen","imagen"},{"estado","id_estado_vehiculo"},{"transmision","transmision"},{"pasajeros","capacidad_pasajeros"},{"anio","anio"},{"color","color"},{"kilometraje","kilometraje"},{"placas","placa"},{"sucursal","id_sucursal"}};var cols=await Query("SELECT COLUMN_NAME,DATA_TYPE FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=N'dbo' AND TABLE_NAME=N'Vehiculos'");var available=cols.Select(x=>Convert.ToString(x["COLUMN_NAME"])!).ToHashSet(StringComparer.OrdinalIgnoreCase);var chosen=new List<(string Column,SqlParameter Param)>();foreach(var kv in map){if(!d.TryGetValue(kv.Key,out var raw)||raw.ValueKind is JsonValueKind.Null or JsonValueKind.Undefined||raw.ToString()==""||!available.Contains(kv.Value))continue;var value=raw;if(kv.Value is "id_categoria" or "id_estado_vehiculo" && raw.ValueKind==JsonValueKind.String&&!int.TryParse(raw.GetString(),out _)){var cat=kv.Value=="id_categoria"?"CategoriasVehiculo":"EstadosVehiculo";var name=kv.Value=="id_categoria"?"nombre":"nombre";var found=await Query($"SELECT TOP 1 id FROM dbo.[{cat}] WHERE LOWER([{name}])=LOWER(@n)",P("@n",SqlDbType.NVarChar,raw.GetString(),80));if(found.Count==0)return Results.BadRequest(new{success=false,message="No se encontró la categoría o estado indicado."});value=JsonDocument.Parse(JsonSerializer.Serialize(found[0]["id"])).RootElement.Clone();}var type=Convert.ToString(cols.First(x=>String.Equals(Convert.ToString(x["COLUMN_NAME"]),kv.Value,StringComparison.OrdinalIgnoreCase))["DATA_TYPE"])!;chosen.Add((kv.Value,JsonParam("@p"+chosen.Count,type,value)));}if(chosen.Count==0)return Results.BadRequest(new{success=false,message="No llegaron campos compatibles del vehículo."});await Exec("INSERT dbo.Vehiculos("+string.Join(',',chosen.Select(x=>$"[{x.Column}]"))+") VALUES("+string.Join(',',chosen.Select(x=>x.Param.ParameterName))+")",chosen.Select(x=>x.Param).ToArray());await Audit(Session(c)!,"Crear vehículo","Vehiculos",null,d);return Results.Json(new{success=true,message="Vehículo agregado."},statusCode:201);}catch(Exception ex){return Error(ex);}});
app.MapPut("/api/admin/vehiculos/{id:int}",async(HttpContext c,int id,JsonElement data)=>{if(Deny(c,"Administrador") is IResult deny)return deny;try{var d=data.Deserialize<Dictionary<string,JsonElement>>(jsonOptions)??new();var map=new Dictionary<string,string>{{"nombre","modelo"},{"marca","marca"},{"categoria","id_categoria"},{"estado","id_estado_vehiculo"},{"pasajeros","capacidad_pasajeros"},{"anio","anio"},{"color","color"},{"kilometraje","kilometraje"},{"placas","placa"},{"sucursal","id_sucursal"}};var cols=await Query("SELECT COLUMN_NAME,DATA_TYPE FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=N'dbo' AND TABLE_NAME=N'Vehiculos'");var set=new List<(string Column,SqlParameter Param)>();foreach(var kv in map){if(!d.TryGetValue(kv.Key,out var raw)||raw.ValueKind is JsonValueKind.Null or JsonValueKind.Undefined||raw.ToString()==""||!cols.Any(x=>String.Equals(Convert.ToString(x["COLUMN_NAME"]),kv.Value,StringComparison.OrdinalIgnoreCase)))continue;var type=Convert.ToString(cols.First(x=>String.Equals(Convert.ToString(x["COLUMN_NAME"]),kv.Value,StringComparison.OrdinalIgnoreCase))["DATA_TYPE"])!;set.Add((kv.Value,JsonParam("@p"+set.Count,type,raw)));}if(set.Count==0)return Results.BadRequest(new{success=false,message="No hay campos compatibles para actualizar."});var n=await Exec("UPDATE dbo.Vehiculos SET "+string.Join(',',set.Select(x=>$"[{x.Column}]={x.Param.ParameterName}"))+" WHERE id=@id",set.Select(x=>x.Param).Append(P("@id",SqlDbType.Int,id)).ToArray());if(n==0)return Results.NotFound(new{success=false,message="Vehículo no encontrado."});await Audit(Session(c)!,"Actualizar vehículo","Vehiculos",id,d);return Results.Ok(new{success=true,message="Vehículo actualizado."});}catch(Exception ex){return Error(ex);}});
app.MapDelete("/api/admin/vehiculos/{id:int}",async(HttpContext c,int id)=>{if(Deny(c,"Administrador") is IResult deny)return deny;try{var n=await Exec("UPDATE dbo.Vehiculos SET retirado=1 WHERE id=@id AND ISNULL(retirado,0)=0",P("@id",SqlDbType.Int,id));if(n==0)return Results.NotFound(new{success=false,message="Vehículo no encontrado o ya retirado."});await Audit(Session(c)!,"Retirar vehículo","Vehiculos",id);return Results.Ok(new{success=true,message="Vehículo eliminado de la flota y del catálogo. Su historial se conservó."});}catch(Exception ex){return Error(ex);}});
