app.MapPost("/api/admin/usuarios",async(HttpContext c,StaffDto d)=>{if(Deny(c,"Administrador") is IResult deny)return deny;if(!Strong(d.password)||!System.Text.RegularExpressions.Regex.IsMatch(d.correo,@"^\S+@\S+\.\S+$")||!System.Text.RegularExpressions.Regex.IsMatch(d.telefono,@"^\d{10}$"))return Results.BadRequest(new{success=false,message="Revisa correo, teléfono y contraseña (8 caracteres, letra, número y símbolo)."});try{var role=(await Query("SELECT nombre_rol FROM dbo.Roles WHERE id=@id",P("@id",SqlDbType.Int,d.id_rol))).FirstOrDefault();if(role is null||Convert.ToString(role["nombre_rol"]) is not("Administrador" or "Empleado"))return Results.BadRequest(new{success=false,message="Selecciona Administrador o Empleado."});await Exec("INSERT dbo.CuentasCliente(nombre,apellido_pat,telefono,correo,contrasena,id_rol,debe_cambiar_contrasena,bloqueada) VALUES(@n,@a,@t,@e,@p,@r,1,0)",P("@n",SqlDbType.NVarChar,d.nombre,50),P("@a",SqlDbType.NVarChar,d.apellido_paterno,50),P("@t",SqlDbType.NVarChar,d.telefono,10),P("@e",SqlDbType.NVarChar,d.correo,100),P("@p",SqlDbType.NVarChar,HashPassword(d.password),255),P("@r",SqlDbType.Int,d.id_rol));await Audit(Session(c)!,"Crear personal","CuentasCliente",d.correo,new{rol=role["nombre_rol"]});return Results.Json(new{success=true,message="Cuenta creada. Debe cambiar la contraseña al iniciar sesión."},statusCode:201);}catch(Exception ex){return Error(ex);}});
app.MapPut("/api/admin/usuarios/{id:int}",async(HttpContext c,int id,JsonElement d)=>{if(Deny(c,"Administrador") is IResult deny)return deny;try{var values=d.Deserialize<Dictionary<string,JsonElement>>(jsonOptions)??new();var map=new Dictionary<string,string>{{"nombre","nombre"},{"apellido_paterno","apellido_pat"},{"apellido_materno","apellido_mat"},{"correo","correo"},{"telefono","telefono"},{"licencia","numero_licencia"},{"id_rol","id_rol"}};var sets=map.Where(x=>values.ContainsKey(x.Key)).ToArray();if(sets.Length==0)return Results.BadRequest(new{success=false,message="No hay cambios válidos."});var ps=sets.Select((x,i)=>P("@p"+i,x.Value=="id_rol"?SqlDbType.Int:SqlDbType.NVarChar,values[x.Key].ToString(),120)).ToArray();await Exec("UPDATE dbo.CuentasCliente SET "+string.Join(',',sets.Select((x,i)=>$"[{x.Value}]=@p{i}"))+" WHERE id=@id",ps.Append(P("@id",SqlDbType.Int,id)).ToArray());await Audit(Session(c)!,"Actualizar cuenta","CuentasCliente",id);return Results.Ok(new{success=true,message="Cuenta actualizada."});}catch(Exception ex){return Error(ex);}});
app.MapPost("/api/admin/usuarios/{id:int}/bloqueo",async(HttpContext c,int id,BanDto d)=>{if(Deny(c,"Administrador") is IResult deny)return deny;if(d.bloqueada&&Session(c)!.Id==id)return Results.BadRequest(new{success=false,message="No puedes bloquear tu propia cuenta."});try{await Proc("dbo.sp_BloquearCuenta",new[]{P("@id_cuenta",SqlDbType.Int,id),P("@bloqueada",SqlDbType.Bit,d.bloqueada)});await Audit(Session(c)!,d.bloqueada?"Bloquear":"Desbloquear","CuentasCliente",id);return Results.Ok(new{success=true,message=d.bloqueada?"Cuenta bloqueada.":"Cuenta desbloqueada."});}catch(Exception ex){return Error(ex);}});
app.MapDelete("/api/admin/usuarios/{id:int}",async(HttpContext c,int id)=>{if(Deny(c,"Administrador") is IResult deny)return deny;if(Session(c)!.Id==id)return Results.BadRequest(new{success=false,message="No puedes eliminar tu propia cuenta."});try{await Exec("DELETE dbo.CuentasCliente WHERE id=@id",P("@id",SqlDbType.Int,id));await Audit(Session(c)!,"Eliminar cuenta","CuentasCliente",id);return Results.Ok(new{success=true,message="Cuenta eliminada."});}catch(Exception ex){return Error(ex);}});

