app.MapGet("/api/admin/reservaciones",async(HttpContext c)=>{if(Deny(c,"Administrador") is IResult deny)return deny;try{return Results.Ok(await Query("SELECT r.id,c.nombre+' '+c.apellido_pat cliente,v.marca,v.modelo,v.placa,r.fecha_inicio,r.fecha_fin,r.costo_total,COALESCE((SELECT SUM(p.monto) FROM dbo.Pagos p JOIN dbo.EstadosPago ep ON ep.id=p.id_estado_pago WHERE p.id_reservacion=r.id AND ep.nombre=N'Pagado'),0) total_pagado,er.nombre estado FROM dbo.Reservaciones r JOIN dbo.CuentasCliente c ON c.id=r.id_cuenta_cliente JOIN dbo.Vehiculos v ON v.id=r.id_vehiculo JOIN dbo.EstadosReservacion er ON er.id=r.id_estado_reservacion ORDER BY r.id DESC"));}catch(Exception ex){return Error(ex);}});
app.MapGet("/api/empleado/reservaciones",async(HttpContext c)=>{if(Deny(c,"Empleado") is IResult deny)return deny;try{return Results.Ok(await Query("SELECT r.id,c.nombre+' '+c.apellido_pat cliente,v.marca,v.modelo,v.placa,r.fecha_inicio,r.fecha_fin,r.costo_total,COALESCE((SELECT SUM(p.monto) FROM dbo.Pagos p JOIN dbo.EstadosPago ep ON ep.id=p.id_estado_pago WHERE p.id_reservacion=r.id AND ep.nombre=N'Pagado'),0) total_pagado,er.nombre estado FROM dbo.Reservaciones r JOIN dbo.CuentasCliente c ON c.id=r.id_cuenta_cliente JOIN dbo.Vehiculos v ON v.id=r.id_vehiculo JOIN dbo.EstadosReservacion er ON er.id=r.id_estado_reservacion ORDER BY r.id DESC"));}catch(Exception ex){return Error(ex);}});
app.MapPost("/api/reservaciones",async(HttpContext c,ReservationDto d)=>{if(Deny(c) is IResult deny)return deny;try{if(string.Equals(Environment.GetEnvironmentVariable("REQUIRE_VERIFIED_EMAIL"),"true",StringComparison.OrdinalIgnoreCase)){var verified=(await Query("SELECT correo_verificado FROM dbo.CuentasCliente WHERE id=@id",P("@id",SqlDbType.Int,Session(c)!.Id))).FirstOrDefault();if(verified is null||!Convert.ToBoolean(verified["correo_verificado"]))return Results.Json(new{success=false,message="Verifica tu correo desde Mis reservaciones antes de reservar."},statusCode:403);}var branch=(await Query("SELECT id_sucursal FROM dbo.Vehiculos WHERE id=@id AND ISNULL(retirado,0)=0",P("@id",SqlDbType.Int,d.vehiculo_id))).FirstOrDefault();if(branch is null)return Results.NotFound(new{success=false,message="No existe ese vehículo."});var output=Out("@id_reservacion",SqlDbType.Int);await Proc("dbo.sp_CrearReservacion",new[]{P("@id_cuenta_cliente",SqlDbType.Int,Session(c)!.Id),P("@id_vehiculo",SqlDbType.Int,d.vehiculo_id),P("@id_sucursal_recogida",SqlDbType.Int,branch["id_sucursal"]),P("@id_sucursal_entrega",SqlDbType.Int,d.id_sucursal_entrega==0?branch["id_sucursal"]:d.id_sucursal_entrega),P("@fecha_inicio",SqlDbType.DateTime2,d.fecha_inicio),P("@fecha_fin",SqlDbType.DateTime2,d.fecha_fin),output});return Results.Json(new{success=true,message="Reservación creada. Continúa con el pago.",id=output.Value},statusCode:201);}catch(Exception ex){return Error(ex);}});
