app.MapGet("/api/reservaciones/{id:int}/pago",async(HttpContext c,int id)=>{if(Deny(c) is IResult deny)return deny;try{var row=(await Query("SELECT r.id,r.id_cuenta_cliente,r.costo_total,COALESCE((SELECT SUM(monto) FROM dbo.Pagos p JOIN dbo.EstadosPago ep ON ep.id=p.id_estado_pago WHERE p.id_reservacion=r.id AND ep.nombre=N'Pagado'),0) pagado,er.nombre estado FROM dbo.Reservaciones r JOIN dbo.EstadosReservacion er ON er.id=r.id_estado_reservacion WHERE r.id=@id",P("@id",SqlDbType.Int,id))).FirstOrDefault();if(row is null||Convert.ToInt32(row["id_cuenta_cliente"])!=Session(c)!.Id)return Results.NotFound();return Results.Ok(new{id,total=row["costo_total"],pagado=row["pagado"],saldo=Convert.ToDecimal(row["costo_total"])-Convert.ToDecimal(row["pagado"]),estado=row["estado"],metodos=await Query("SELECT id,nombre FROM dbo.MetodosPago ORDER BY id")});}catch(Exception ex){return Error(ex);}});
app.MapPost("/api/reservaciones/{id:int}/pago",async(HttpContext c,int id,PaymentDto d)=>{if(Deny(c) is IResult deny)return deny;try{var output=Out("@id_pago",SqlDbType.Int);await Proc("dbo.sp_RegistrarPago",new[]{P("@id_reservacion",SqlDbType.Int,id),P("@id_metodo_pago",SqlDbType.Int,d.id_metodo_pago),P("@monto",SqlDbType.Decimal,d.monto),P("@referencia",SqlDbType.NVarChar,d.referencia,100),output});var row=(await Reservations("WHERE r.id=@id",P("@id",SqlDbType.Int,id))).First();return Results.Ok(new{success=true,message="Pago registrado.",id_pago=output.Value,pagado=row["total_pagado"],total=row["costo_total"],completo=Convert.ToDecimal(row["total_pagado"])>=Convert.ToDecimal(row["costo_total"])});}catch(Exception ex){return Error(ex);}});
app.MapGet("/api/reservaciones/{id:int}/comprobante",async(HttpContext c,int id)=>{if(Deny(c) is IResult deny)return deny;try{var u=Session(c)!;var row=(await Reservations("WHERE r.id=@id",P("@id",SqlDbType.Int,id))).FirstOrDefault();if(row is null||Convert.ToInt32(row["id_cuenta_cliente"])!=u.Id&&u.Role!="Administrador"||Convert.ToDecimal(row["total_pagado"])<Convert.ToDecimal(row["costo_total"]))return Results.Json(new{success=false,message="El comprobante está disponible después de liquidar la reservación."},statusCode:403);return Results.Ok(new{reservacion=row,pagos=await Query("SELECT p.id,p.monto,p.fecha_pago,p.referencia,mp.nombre metodo FROM dbo.Pagos p JOIN dbo.EstadosPago ep ON ep.id=p.id_estado_pago JOIN dbo.MetodosPago mp ON mp.id=p.id_metodo_pago WHERE p.id_reservacion=@id AND ep.nombre=N'Pagado' ORDER BY p.fecha_pago",P("@id",SqlDbType.Int,id))});}catch(Exception ex){return Error(ex);}});
