app.MapGet("/api/admin/ingresos",async(HttpContext c,DateTime desde,DateTime hasta)=>{if(Deny(c,"Administrador") is IResult deny)return deny;try{var(r,o)=await Proc("dbo.sp_IngresosPorPeriodo",new[]{P("@fecha_inicio",SqlDbType.DateTime2,desde),P("@fecha_fin",SqlDbType.DateTime2,hasta)});var total=await Query("SELECT COALESCE(SUM(p.monto),0) total_general FROM dbo.Pagos p JOIN dbo.EstadosPago e ON e.id=p.id_estado_pago WHERE e.nombre=N'Pagado' AND p.fecha_pago>=@a AND p.fecha_pago<@b",P("@a",SqlDbType.DateTime2,desde),P("@b",SqlDbType.DateTime2,hasta));return Results.Ok(new{porMetodo=r,total=total.FirstOrDefault()?["total_general"]??0});}catch(Exception ex){return Error(ex);}});
app.MapGet("/api/admin/estadisticas",async(HttpContext c)=>{if(Deny(c,"Administrador") is IResult deny)return deny;try{var x=(await Query("SELECT (SELECT COUNT(*) FROM dbo.Vehiculos WHERE ISNULL(retirado,0)=0) vehiculos,(SELECT COUNT(*) FROM dbo.CuentasCliente) usuarios,(SELECT COUNT(*) FROM dbo.Reservaciones) reservaciones,(SELECT COUNT(*) FROM dbo.Pagos) pagos,(SELECT COALESCE(SUM(p.monto),0) FROM dbo.Pagos p JOIN dbo.EstadosPago e ON e.id=p.id_estado_pago WHERE e.nombre=N'Pagado') ingresos,(SELECT AVG(CAST(calificacion AS float)) FROM dbo.Opiniones) calificacion")).First();x["reservacionesPorEstado"]=await Query("SELECT e.nombre,COUNT(r.id) total FROM dbo.EstadosReservacion e LEFT JOIN dbo.Reservaciones r ON r.id_estado_reservacion=e.id GROUP BY e.nombre ORDER BY e.nombre");x["flotaPorEstado"]=await Query("SELECT e.nombre,COUNT(v.id) total FROM dbo.EstadosVehiculo e LEFT JOIN dbo.Vehiculos v ON v.id_estado_vehiculo=e.id AND ISNULL(v.retirado,0)=0 GROUP BY e.nombre ORDER BY e.nombre");return Results.Ok(x);}catch(Exception ex){return Error(ex);}});

app.MapGet("/api/admin/tablas",(HttpContext c)=>Deny(c,"Administrador") is IResult deny?deny:Results.Ok(roles));
app.MapGet("/api/admin/tablas/{tabla}",async(HttpContext c,string tabla,int pagina=1)=>{if(Deny(c,"Administrador") is IResult deny)return deny;if(!roles.Contains(tabla))return Results.NotFound();try{var cols=await Query("SELECT COLUMN_NAME,DATA_TYPE,IS_NULLABLE,ORDINAL_POSITION FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=N'dbo' AND TABLE_NAME=@t ORDER BY ORDINAL_POSITION",P("@t",SqlDbType.NVarChar,tabla,128));var total=(await Query($"SELECT COUNT(*) total FROM dbo.[{tabla}]"))[0]["total"];var rows=await Query($"SELECT * FROM dbo.[{tabla}] ORDER BY 1 DESC OFFSET @o ROWS FETCH NEXT 100 ROWS ONLY",P("@o",SqlDbType.Int,Math.Max(0,pagina-1)*100));var safe=rows.Select(row=>row.Where(kv=>!new[]{"contrasena","debe_cambiar_contrasena"}.Contains(kv.Key,StringComparer.OrdinalIgnoreCase)).ToDictionary()).ToArray();return Results.Ok(new{tabla,columnas=cols.Where(x=>!new[]{"contrasena","debe_cambiar_contrasena"}.Contains(Convert.ToString(x["COLUMN_NAME"]),StringComparer.OrdinalIgnoreCase)),filas=safe,total,pagina,paginas=Math.Max(1,(Convert.ToInt32(total)+99)/100)});}catch(Exception ex){return Error(ex);}});
app.MapPost("/api/admin/tablas/{tabla}",async(HttpContext c,string tabla,JsonElement data)=>{if(Deny(c,"Administrador") is IResult deny)return deny;if(!roles.Contains(tabla))return Results.NotFound();try{var cols=await Query("SELECT COLUMN_NAME,DATA_TYPE,IS_NULLABLE FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=N'dbo' AND TABLE_NAME=@t",P("@t",SqlDbType.NVarChar,tabla,128));var values=data.Deserialize<Dictionary<string,JsonElement>>(jsonOptions)??new();var chosen=cols.Where(col=>values.ContainsKey(Convert.ToString(col["COLUMN_NAME"])!)&&!Convert.ToString(col["COLUMN_NAME"])!.Equals("id",StringComparison.OrdinalIgnoreCase)&&!new[]{"contrasena","debe_cambiar_contrasena"}.Contains(Convert.ToString(col["COLUMN_NAME"]),StringComparer.OrdinalIgnoreCase)).ToArray();var ps=new List<SqlParameter>();if(tabla=="CuentasCliente"){if(!values.TryGetValue("contrasena",out var pw)||!Strong(pw.GetString()))return Results.BadRequest(new{success=false,message="Contraseña: 8 caracteres, letra, número y símbolo."});var roleId=values.ContainsKey("id_rol")?values["id_rol"].GetInt32():Convert.ToInt32((await Query("SELECT id FROM dbo.Roles WHERE nombre_rol=N'Cliente'"))[0]["id"]);ps.Add(P("@role",SqlDbType.Int,roleId));ps.Add(P("@pass",SqlDbType.NVarChar,HashPassword(pw.GetString()!),255));}
var fields=chosen.Select((col,i)=>{var name=Convert.ToString(col["COLUMN_NAME"])!;var key=name;var param="@v"+i;ps.Add(JsonParam(param,Convert.ToString(col["DATA_TYPE"])!,values[key]));return($"[{name}]",param);}).ToList();if(tabla=="CuentasCliente"){fields.Add(("[contrasena]","@pass"));if(!fields.Any(x=>x.Item1=="[id_rol]"))fields.Add(("[id_rol]","@role"));if(cols.Any(x=>Convert.ToString(x["COLUMN_NAME"])=="bloqueada"))fields.Add(("[bloqueada]","@blocked"));if(fields.Any(x=>x.Item1=="[bloqueada]"))ps.Add(P("@blocked",SqlDbType.Bit,false));}
if(fields.Count==0)return Results.BadRequest(new{success=false,message="Agrega campos al registro."});await Exec($"INSERT dbo.[{tabla}]({string.Join(',',fields.Select(x=>x.Item1))}) VALUES({string.Join(',',fields.Select(x=>x.Item2))})",ps.ToArray());await Audit(Session(c)!,"Crear registro",tabla,null);return Results.Json(new{success=true,message="Registro creado."},statusCode:201);}catch(Exception ex){return Error(ex);}});
app.MapPut("/api/admin/tablas/{tabla}/{id:int}",async(HttpContext c,string tabla,int id,JsonElement data)=>{if(Deny(c,"Administrador") is IResult deny)return deny;if(!roles.Contains(tabla))return Results.NotFound();try{var cols=await Query("SELECT COLUMN_NAME,DATA_TYPE FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=N'dbo' AND TABLE_NAME=@t",P("@t",SqlDbType.NVarChar,tabla,128));var values=data.Deserialize<Dictionary<string,JsonElement>>(jsonOptions)??new();var ps=new List<SqlParameter>{P("@id",SqlDbType.Int,id)};var sets=new List<string>();foreach(var col in cols){var name=Convert.ToString(col["COLUMN_NAME"])!;if(name.Equals("id",StringComparison.OrdinalIgnoreCase)||new[]{"contrasena","debe_cambiar_contrasena"}.Contains(name,StringComparer.OrdinalIgnoreCase)||!values.ContainsKey(name))continue;var p="@p"+sets.Count;ps.Add(JsonParam(p,Convert.ToString(col["DATA_TYPE"])!,values[name]));sets.Add($"[{name}]={p}");}if(tabla=="CuentasCliente"&&values.TryGetValue("contrasena",out var pw)&&pw.ValueKind==JsonValueKind.String&&Strong(pw.GetString())){ps.Add(P("@pass",SqlDbType.NVarChar,HashPassword(pw.GetString()!),255));sets.Add("contrasena=@pass");}if(sets.Count==0)return Results.BadRequest(new{success=false,message="No hay cambios válidos."});await Exec($"UPDATE dbo.[{tabla}] SET {string.Join(',',sets)} WHERE id=@id",ps.ToArray());await Audit(Session(c)!,"Actualizar registro",tabla,id);return Results.Ok(new{success=true,message="Cambios guardados."});}catch(Exception ex){return Error(ex);}});
