 issues=new[]{v.Issue,customers.Issue,gps.Issue,reviews.Issue,owners.Issue,docs.Issue,invoices.Issue}.Where(x=>x is not null).ToArray();return Results.Ok(new{vehiculos=v.Rows,clientes=customers.Rows,gps=gps.Rows,evaluaciones=reviews.Rows,propuestas=owners.Rows,verificaciones=docs.Rows,facturas=invoices.Rows,diagnosticos=issues});});app.MapGet("/api/ubicaciones-gps",async(HttpContext c)=>{if(Deny(c,"Administrador") is IResult deny && Session(c)?.Role!="Empleado")return deny;try{return Results.Ok(await Query("SELECT TOP 200 g.id,g.id_vehiculo,v.marca,v.modelo,v.placa,g.latitud,g.longitud,g.fecha,g.fuente FROM dbo.UbicacionesGPS g JOIN dbo.Vehiculos v ON v.id=g.id_vehiculo ORDER BY g.fecha DESC"));}catch(Exception ex){return Error(ex);}});
