app.MapPost("/api/reservaciones/{id:int}/solicitud-factura",async(HttpContext c,int id,InvoiceRequestDto d)=>{if(Deny(c) is IResult deny)return deny;var u=Session(c)!;if(!System.Text.RegularExpressions.Regex.IsMatch(d.rfc??"",@"^[A-Z&Ñ]{3,4}\d{6}[A-Z0-9]{3}$")||!System.Text.RegularExpressions.Regex.IsMatch(d.codigo_postal??"",@"^\d{5}$"))return Results.BadRequest(new{success=false,message="Revisa RFC y código postal fiscal."});try{var paid=(await Reservations("WHERE r.id=@id AND r.id_cuenta_cliente=@u",P("@id",SqlDbType.Int,id),P("@u",SqlDbType.Int,u.Id))).FirstOrDefault();if(paid is null)return Results.NotFound();if(Convert.ToDecimal(paid["total_pagado"])<Convert.ToDecimal(paid["costo_total"]))return Results.BadRequest(new{success=false,message="La reservación debe estar pagada para solicitar factura."});await Exec("INSERT dbo.SolicitudesFactura(id_reservacion,id_cliente,rfc,razon_social,codigo_postal,regimen_fiscal,uso_cfdi,correo) VALUES(@r,@c,@f,@n,@cp,@reg,@uso,@e)",P("@r",SqlDbType.Int,id),P("@c",SqlDbType.Int,u.Id),P("@f",SqlDbType.NVarChar,d.rfc!.ToUpperInvariant(),13),P("@n",SqlDbType.NVarChar,d.razon_social,160),P("@cp",SqlDbType.NVarChar,d.codigo_postal,5),P("@reg",SqlDbType.NVarChar,d.regimen_fiscal,10),P("@uso",SqlDbType.NVarChar,d.uso_cfdi,10),P("@e",SqlDbType.NVarChar,u.Email,150));return Results.Json(new{success=true,message="Solicitud recibida, pendiente de timbrado con SAT/PAC. El comprobante actual no es CFDI."},statusCode:201);}catch(Exception ex){return Error(ex);}});
