app.MapPost("/api/email-verificacion/solicitar",async(HttpContext c)=>{if(Deny(c) is IResult deny)return deny;var host=Environment.GetEnvironmentVariable("SMTP_HOST");var from=Environment.GetEnvironmentVariable("SMTP_FROM");var user=Environment.GetEnvironmentVariable("SMTP_USER");var pass=Environment.GetEnvironmentVariable("SMTP_PASSWORD");if(string.IsNullOrWhiteSpace(host)||string.IsNullOrWhiteSpace(from)||string.IsNullOrWhiteSpace(user)||string.IsNullOrWhiteSpace(pass))return Results.Json(new{success=false,message="La verificación por correo está lista para configurar, pero falta SMTP_HOST, SMTP_FROM, SMTP_USER y SMTP_PASSWORD en .env."},statusCode:503);var u=Session(c)!;try{var token=Convert.ToHexString(RandomNumberGenerator.GetBytes(32));var hash=SHA256.HashData(Encoding.UTF8.GetBytes(token));await Exec("DELETE dbo.VerificacionCorreo WHERE id_cliente=@id; INSERT dbo.VerificacionCorreo(id_cliente,token_hash,expira) VALUES(@id,@hash,DATEADD(MINUTE,30,SYSDATETIME()))",P("@id",SqlDbType.Int,u.Id),P("@hash",SqlDbType.VarBinary,hash));var port=int.TryParse(Environment.GetEnvironmentVariable("SMTP_PORT"),out var p)?p:587;using var smtp=new SmtpClient(host,port){EnableSsl=!string.Equals(Environment.GetEnvironmentVariable("SMTP_SSL"),"false",StringComparison.OrdinalIgnoreCase),Credentials=new NetworkCredential(user,pass)};var link=$"{c.Request.Scheme}://{c.Request.Host}/verificar-correo.html?token={Uri.EscapeDataString(token)}";using var mail=new MailMessage(from,u.Email){Subject="Verifica tu correo · Mexico Runs",Body="Abre este enlace en los próximos 30 minutos para confirmar que tienes acceso a este correo: "+link};await smtp.SendMailAsync(mail);return Results.Ok(new{success=true,message="Enlace enviado. Revisa tu bandeja y correo no deseado."});}catch{await Exec("DELETE dbo.VerificacionCorreo WHERE id_cliente=@id",P("@id",SqlDbType.Int,u.Id));return Results.Json(new{success=false,message="No se pudo enviar el correo. Revisa la configuración SMTP."},statusCode:502);}});
app.MapPost("/api/email-verificacion/confirmar",async(ConfirmEmailDto d)=>{if(string.IsNullOrWhiteSpace(d.token)||d.token.Length>128)return Results.BadRequest(new{success=false,message="Enlace inválido o vencido."});try{var hash=SHA256.HashData(Encoding.UTF8.GetBytes(d.token));var row=(await Query("SELECT TOP 1 id_cliente FROM dbo.VerificacionCorreo WHERE token_hash=@h AND expira>SYSDATETIME()",P("@h",SqlDbType.VarBinary,hash))).FirstOrDefault();if(row is null)return Results.BadRequest(new{success=false,message="Enlace inválido o vencido. Solicita otro."});var id=Convert.ToInt32(row["id_cliente"]);await Exec("UPDATE dbo.CuentasCliente SET correo_verificado=1 WHERE id=@id; DELETE dbo.VerificacionCorreo WHERE id_cliente=@id",P("@id",SqlDbType.Int,id));return Results.Ok(new{success=true,message="Correo verificado. Esto confirma acceso al buzón, no garantiza la existencia legal de la persona."});}catch(Exception ex){return Error(ex);}});
