app.MapPost("/api/integraciones/gps/{idVehiculo:int}",async(HttpContext c,int idVehiculo,GpsIngestDto d)=>{var expected=Environment.GetEnvironmentVariable("GPS_INGEST_API_KEY");var supplied=c.Request.Headers["X-GPS-API-Key"].ToString();if(string.IsNullOrWhiteSpace(expected))return Results.Json(new{success=false,message="La integración GPS no está configurada."},statusCode:503);if(string.IsNullOrWhiteSpace(supplied)||!CryptographicOperations.FixedTimeEquals(Encoding.UTF8.GetBytes(expected),Encoding.UTF8.GetBytes(supplied)))return Results.Unauthorized();if(d.latitud is <-90 or >90||d.longitud is <-180 or >180)return Results.BadRequest(new{success=false,message="Coordenadas inválidas."});try{var exists=(await Query("SELECT 1 existe FROM dbo.Vehiculos WHERE id=@id AND ISNULL(retirado,0)=0",P("@id",SqlDbType.Int,idVehiculo))).Any();if(!exists)return Results.NotFound(new{success=false,message="Vehículo no encontrado."});await Exec("INSERT dbo.UbicacionesGPS(id_vehiculo,latitud,longitud,fuente) VALUES(@id,@lat,@lon,N'Proveedor GPS')",P("@id",SqlDbType.Int,idVehiculo),P("@lat",SqlDbType.Decimal,d.latitud),P("@lon",SqlDbType.Decimal,d.longitud));return Results.Ok(new{success=true});}catch(Exception ex){return Error(ex);}});
