SqlParameter JsonParam(string name,string type,JsonElement value){var t=type switch{"int"=>SqlDbType.Int,"bigint"=>SqlDbType.BigInt,"smallint"=>SqlDbType.SmallInt,"tinyint"=>SqlDbType.TinyInt,"bit"=>SqlDbType.Bit,"decimal" or "numeric" or "money"=>SqlDbType.Decimal,"float"=>SqlDbType.Float,"date"=>SqlDbType.Date,"datetime" or "datetime2"=>SqlDbType.DateTime2,"time"=>SqlDbType.Time,_=>SqlDbType.NVarChar};object? v=value.ValueKind switch{JsonValueKind.Null or JsonValueKind.Undefined=>null,JsonValueKind.True=>true,JsonValueKind.False=>false,JsonValueKind.Number when t==SqlDbType.Int=>value.GetInt32(),JsonValueKind.Number when t==SqlDbType.Decimal=>value.GetDecimal(),JsonValueKind.Number when t==SqlDbType.Float=>value.GetDouble(),JsonValueKind.String when t is SqlDbType.Date or SqlDbType.DateTime2 or SqlDbType.Time=>DateTime.Parse(value.GetString()!),JsonValueKind.String=>value.GetString(),_=>value.ToString()};return P(name,t,v,t==SqlDbType.NVarChar?-1:0);}
