static class Scrypt
{
    public static byte[] Hash(string password, byte[] salt, int n, int r, int p, int length)
    {
        var b = Rfc2898DeriveBytes.Pbkdf2(Encoding.UTF8.GetBytes(password), salt, 1, HashAlgorithmName.SHA256, p * 128 * r);
        for (int i = 0; i < p; i++) Smix(b, i * 128 * r, r, n);
        return Rfc2898DeriveBytes.Pbkdf2(Encoding.UTF8.GetBytes(password), b, 1, HashAlgorithmName.SHA256, length);
    }
    static uint Rot(uint x,int n)=>(x<<n)|(x>>(32-n));
    static void Salsa8(uint[] b)
    {
        var x=(uint[])b.Clone();
        for(int i=0;i<8;i+=2){
            x[4]^=Rot(x[0]+x[12],7);x[8]^=Rot(x[4]+x[0],9);x[12]^=Rot(x[8]+x[4],13);x[0]^=Rot(x[12]+x[8],18);
            x[9]^=Rot(x[5]+x[1],7);x[13]^=Rot(x[9]+x[5],9);x[1]^=Rot(x[13]+x[9],13);x[5]^=Rot(x[1]+x[13],18);
            x[14]^=Rot(x[10]+x[6],7);x[2]^=Rot(x[14]+x[10],9);x[6]^=Rot(x[2]+x[14],13);x[10]^=Rot(x[6]+x[2],18);
            x[3]^=Rot(x[15]+x[11],7);x[7]^=Rot(x[3]+x[15],9);x[11]^=Rot(x[7]+x[3],13);x[15]^=Rot(x[11]+x[7],18);
            x[1]^=Rot(x[0]+x[3],7);x[2]^=Rot(x[1]+x[0],9);x[3]^=Rot(x[2]+x[1],13);x[0]^=Rot(x[3]+x[2],18);
            x[6]^=Rot(x[5]+x[4],7);x[7]^=Rot(x[6]+x[5],9);x[4]^=Rot(x[7]+x[6],13);x[5]^=Rot(x[4]+x[7],18);
            x[11]^=Rot(x[10]+x[9],7);x[8]^=Rot(x[11]+x[10],9);x[9]^=Rot(x[8]+x[11],13);x[10]^=Rot(x[9]+x[8],18);
            x[12]^=Rot(x[15]+x[14],7);x[13]^=Rot(x[12]+x[15],9);x[14]^=Rot(x[13]+x[12],13);x[15]^=Rot(x[14]+x[13],18);
        }
        for(int i=0;i<16;i++)b[i]+=x[i];
    }
    static void BlockMix(uint[] b,int r)
    {
        var x=new uint[16];Array.Copy(b,(2*r-1)*16,x,0,16);var y=new uint[32*r];
        for(int i=0;i<2*r;i++){for(int j=0;j<16;j++)x[j]^=b[i*16+j];Salsa8(x);Array.Copy(x,0,y,i*16,16);}
        for(int i=0;i<r;i++){Array.Copy(y,(2*i)*16,b,i*16,16);Array.Copy(y,(2*i+1)*16,b,(i+r)*16,16);}
    }
    static void Smix(byte[] b,int offset,int r,int n)
    {
        int words=32*r;var x=new uint[words];for(int i=0;i<words;i++)x[i]=BitConverter.ToUInt32(b,offset+i*4);var v=new uint[n*words];
        for(int i=0;i<n;i++){Array.Copy(x,0,v,i*words,words);BlockMix(x,r);}
        for(int i=0;i<n;i++){int j=(int)(x[(2*r-1)*16]&((uint)n-1));int at=j*words;for(int k=0;k<words;k++)x[k]^=v[at+k];BlockMix(x,r);}
        for(int i=0;i<words;i++)BitConverter.TryWriteBytes(b.AsSpan(offset+i*4,4),x[i]);
    }
}








